import fs from 'node:fs';
import path from 'node:path';
// Counts the marker in each file it is given; the marker is spelled apart so this file holds none.
const MARK = new RegExp(['PL', 'ANT'].join(''), 'g');
export function collect({ root, paths }) {
  return paths.flatMap((p) => (fs.readFileSync(path.join(root, p), 'utf8').match(MARK) ?? []).map(() => ({ rule: 'plant', path: p })));
}
